// Public, static install assets. No private content caching.
export const galleryManifest = "{\"id\":\"/\",\"name\":\"我的相册\",\"short_name\":\"相册\",\"description\":\"私人照片、视频与网盘回忆\",\"lang\":\"zh-CN\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#101114\",\"theme_color\":\"#101114\",\"icons\":[{\"src\":\"/@gallery-icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any maskable\"},{\"src\":\"/@gallery-icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any maskable\"}]}"
export const galleryServiceWorker = "// Network-only service worker. Do not cache credentials, metadata, private media or API responses.\nself.addEventListener(\"install\",()=>self.skipWaiting());\nself.addEventListener(\"activate\",e=>e.waitUntil(self.clients.claim()));\nself.addEventListener(\"fetch\",e=>{const u=new URL(e.request.url);if(e.request.method===\"GET\"&&u.origin===self.location.origin&&[\"/@gallery.css\",\"/@gallery.js\",\"/@gallery.webmanifest\"].includes(u.pathname))e.respondWith(fetch(e.request));});\n"
const icons: Record<string,string> = {"180":"","192":"","512":""}
export function galleryIcon(size: string) { const data=icons[size];return data ? Uint8Array.from(atob(data),c=>c.charCodeAt(0)) : null }
